namespace RonSijm.FluidHumidifier.Factories.SecurityAgent;

public class InnerIntegrationProviderInputFactory(Action<Humidifier.SecurityAgent.IntegrationTypes.ProviderInput> factoryAction = null) : SubResourceFactory<Humidifier.SecurityAgent.IntegrationTypes.ProviderInput>
{

    internal InnerIntegrationGitHubInputFactory GithubFactory { get; set; }

    internal InnerIntegrationConfluenceInputFactory ConfluenceFactory { get; set; }

    internal InnerIntegrationBitbucketInputFactory BitbucketFactory { get; set; }

    internal InnerIntegrationGitLabInputFactory GitlabFactory { get; set; }

    protected override Humidifier.SecurityAgent.IntegrationTypes.ProviderInput Create()
    {
        var providerInputResult = CreateProviderInput();
        factoryAction?.Invoke(providerInputResult);

        return providerInputResult;
    }

    private Humidifier.SecurityAgent.IntegrationTypes.ProviderInput CreateProviderInput()
    {
        var providerInputResult = new Humidifier.SecurityAgent.IntegrationTypes.ProviderInput();

        return providerInputResult;
    }
    public override void CreateChildren(Humidifier.SecurityAgent.IntegrationTypes.ProviderInput result)
    {
        base.CreateChildren(result);

        result.Github ??= GithubFactory?.Build();
        result.Confluence ??= ConfluenceFactory?.Build();
        result.Bitbucket ??= BitbucketFactory?.Build();
        result.Gitlab ??= GitlabFactory?.Build();
    }

} // End Of Class

